 Setup();T(3,3).prop=T(4,3).prop=PropKind.Crate;g.View.Initialize(g.State);g.Select(3,3);g.ApplyTool();Check(!g.Busy&&g.ActionCount==0&&g.State.carryingProp==PropKind.None&&T(4,3).prop==PropKind.Crate,"chain push and pickup both rejected");
 Setup();g.State.boatCrates=1;g.TransferCargo(true);Check(g.State.boatCrates==0&&T(3,3).prop==PropKind.Crate&&g.State.carryingProp==PropKind.None,"ship unloads directly to facing cell without hand-held box");g.TransferCargo(false);Check(g.State.boatCrates==1&&T(3,3).prop==PropKind.None,"ship loads adjacent crate without carrying");
 var saved=typeof(HabitatGame).GetMethod("ReadValidatedSnapshot",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{Dir+"/full-campaign-first.json"});Call(g,"RestoreSnapshot",saved);g.Hud.ClosePanels();g.paused=true;g.tool=0;var fish=g.State.animals.First(a=>a.species==Species.Goldfish);var spots=new[]{new Vector2Int(fish.x-1,fish.z),new Vector2Int(fish.x+1,fish.z),new Vector2Int(fish.x,fish.z-1),new Vector2Int(fish.x,fish.z+1)};var spot=spots.First(v=>HabitatRules.Inside(g.State,v.x,v.y)&&!HabitatRules.IsWater(g.State,v.x,v.y));g.State.playerX=spot.x;g.State.playerZ=spot.y;g.View.Initialize(g.State);g.Select(spot.x,spot.y);await Frame();g.Hud.ClosePanels();
 Check(g.TryNearbyCatch(out int fx,out int fz)&&fx==fish.x&&fz==fish.z,"adjacent catch found while interaction tool selected");string label=(string)Call(g.Hud,"ContextActionLabel");Check(label.Contains("钓起小鱼"),"fish has direct E/click prompt");for(int i=0;i<15;i++)await Frame();g.Hud.ClosePanels();g.Hud.Refresh();Call(g.Hud,"RefreshPlanHud");Check(((GameObject)typeof(HabitatHud).GetField("contextPanel",F).GetValue(g.Hud)).activeInHierarchy,"fish context bubble is actually visible; modal="+g.Hud.ModalOpen+" busy="+g.Busy+" story="+g.StoryPlaying+" self="+((GameObject)typeof(HabitatHud).GetField("contextPanel",F).GetValue(g.Hud)).activeSelf+" parent="+((GameObject)typeof(HabitatHud).GetField("contextPanel",F).GetValue(g.Hud)).transform.parent.gameObject.activeInHierarchy);await Capture("nearby-fishing-prompt");g.ApplyTool();Check(g.Fishing.IsOpen&&g.State.glassFish==0,"E opens existing fishing minigame, no premature reward");g.Fishing.Cancel(false);Check(g.State.glassFish==0,"cancel fishing grants nothing");
